from collections import Counter

class Solution:
    def sumOfUnique(self, nums: List[int]) -> int:
        return sum(x for x, c in Counter(nums).items() if c == 1)

c.cpp:
class Solution {
public:
    int sumOfUnique(vector<int>& nums) {
        unordered_map<int, int> cnt;
        for (int x : nums) cnt[x]++;
        int ans = 0;
        for (auto& [x, c] : cnt) {
            if (c == 1) ans += x;
        }
        return ans;
    }
};

